def chain_chain(nft, jrp):
    chain = []
    current = nft
    while True:
        chain.append(current)
        if current == jrp:
            break
        next_token = current[-1]
        if next_token == 'a':
            current = current[:-1]
        else:
            current = current[:-1] + next_token
    return chain

